// Package codec is the difftest's protobuf codec: generated by ../gen.py from ../protobuf.toml
// (harness/kitgen/pbgen.py) for every message type of pb, qp/raxos and qp/client, as a kit's
// adapter package would have it.
package codec

// Register registers the codec with the protobuf model (a model build); a no-op with the real
// module.
func Register() {
	registerProto()
}
